 void updateNavigation(String cat){for(int i=0;i<nav.getChildCount();i++){View v=nav.getChildAt(i);boolean selected=cat.equals(v.getTag());v.setSelected(selected);if(v instanceof Button)((Button)v).setTextColor(selected?Ui.ACCENT:0xffa8b5c7);if(selected){activeNavigation=(Button)v;pageTitle.setText(names[i]);}}}
 View firstContentFocus(View parent){if(parent==null)return null;if(parent!=body&&parent.isFocusable()&&parent.isEnabled()&&parent.getVisibility()==View.VISIBLE)return parent;if(parent instanceof ViewGroup){ViewGroup group=(ViewGroup)parent;for(int i=0;i<group.getChildCount();i++){View found=firstContentFocus(group.getChildAt(i));if(found!=null)return found;}}return null;}
 String fileSize(double bytes){if(bytes>=1073741824d)return String.format(java.util.Locale.US,"%.1f GB",bytes/1073741824d);if(bytes>=1048576d)return String.format(java.util.Locale.US,"%.1f MB",bytes/1048576d);return String.format(java.util.Locale.US,"%.0f KB",bytes/1024d);}
 void loading(String s){body.removeAllViews();TextView t=text(s,22,Color.WHITE);t.setPadding(dp(15),dp(80),dp(15),dp(20));body.addView(t);}
 void connect(){handler.removeCallbacks(retryConnection);final int ticket=++generation;connection.setText("正在自动连接 · 无需重新输入密码");worker.submit(()->{try{JSONObject s;
  try{api.login();s=api.get("/api/status");}catch(ConnectException|SocketTimeoutException|NoRouteToHostException|UnknownHostException e){if(!api.discover())throw e;api.login();s=api.get("/api/status");}
  final JSONArray found=s.optJSONArray("defaultSources");api.rememberBackend();runOnUiThread(()->{if(ticket!=generation||isFinishing())return;sources=found==null?new JSONArray():found;connected=true;connection.setText("● 已连接电脑 · "+sources.length()+" 个片源 · 连接信息已保存");navigate(current);});
  }catch(Exception error){runOnUiThread(()->{if(ticket!=generation||isFinishing())return;connected=false;connection.setText(api.friendly(error));loading("电脑后台暂不可用，连接信息仍然保留");body.addView(text("电脑开机、网络恢复后会自动重连。\n如后台密码没有变化，不需要重新输入。",17,Ui.MUTED));body.addView(button("立即重连",v->connect()),lp(180,44));body.addView(button("连接设置",v->settings()),lp(180,44));if(!api.friendly(error).contains("密码"))handler.postDelayed(retryConnection,10000);});}});
 }
 void navigate(String cat){current=cat;generation++;suggestionGeneration++;page=0;query=null;searchStatus=null;scroll.scrollTo(0,0);
  updateNavigation(cat);
  if(cat.equals("search")){searchScreen();return;}if(cat.equals("live")){liveScreen();return;}if(cat.equals("nas")){nasScreen("",0);return;}if(!connected){loading("电脑后台尚未连接，连接信息已保留");body.addView(button("重新连接",v->connect()),lp(180,46));return;}loadCatalog(0);
 }
 void loadCatalog(int next){final int ticket=++generation;String cat=current;loading("正在整理片单…");job(()->{JSONObject catalog;
  try{catalog=api.get("/tv/catalog?category="+cat+"&page="+next);}catch(Exception e){JSONObject r=api.get("/api/douban?type="+(cat.equals("tv")||cat.equals("anime")?"tv":"movie")+"&tag="+Api.enc("热门")+"&pageStart="+(next*24));JSONArray a=r.optJSONArray("items"),converted=new JSONArray();if(a!=null)for(int i=0;i<a.length();i++){JSONObject v=a.optJSONObject(i);converted.put(new JSONObject().put("name",v.optString("title")).put("pic",v.optString("cover")).put("remarks",v.optString("rate")).put("recommendation",true));}catalog=new JSONObject().put("items",converted).put("hasMore",converted.length()>0);}
  final JSONObject data=catalog;runOnUiThread(()->{if(ticket==generation&&!isFinishing()){page=next;renderCatalog(data);}});});
 }
