  if(sections!=null&&sections.length()>0){for(int i=0;i<sections.length();i++){JSONObject s=sections.optJSONObject(i);heading(s.optString("title"),"遥控器左右浏览");row(s.optJSONArray("items"),false);}}else{heading(current.equals("movie")?"电影海报墙":"最近更新","由实际可用片源整理");grid(items,5);}
