 void grid(JSONArray list,int cols){
  if(list==null)return;cols=5;for(int i=0;i<Math.min(list.length(),60);i+=cols){LinearLayout line=new LinearLayout(this);
   for(int j=i;j<Math.min(i+cols,list.length());j++){JSONObject item=list.optJSONObject(j);if(item==null)continue;LinearLayout.LayoutParams p=lp(0,225);p.weight=1;line.addView(card(item,false,122),p);}
   for(int j=line.getChildCount();j<cols;j++){LinearLayout.LayoutParams p=lp(0,225);p.weight=1;line.addView(new View(this),p);}body.addView(line);
  }
 }
 void settings(){LinearLayout form=column();form.setPadding(dp(22),dp(8),dp(22),dp(8));form.addView(text("电脑重启或网络恢复后自动重新登录，不必重输密码。",16,Color.WHITE));EditText host=new EditText(this);host.setSingleLine();host.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_URI);host.setText(api.server());form.addView(host);EditText pass=new EditText(this);pass.setSingleLine();pass.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);pass.setText(api.prefs.getString("password",""));form.addView(pass);form.addView(text("连接信息保存于电视。覆盖安装保留；卸载/清空数据会清除。IP变化时会尝试发现此前连接的电脑。",13,Ui.MUTED));AlertDialog d=new AlertDialog.Builder(this).setTitle("连接设置").setView(form).setNegativeButton("取消",null).setNeutralButton("重新连接",(x,w)->connect()).setPositiveButton("保存连接",null).create();d.setOnShowListener(x->d.getButton(-1).setOnClickListener(v->{String s=host.getText().toString().trim();if(!s.contains("://"))s="http://"+s;try{URI u=new URI(s);if(u.getHost()==null||!("http".equals(u.getScheme())||"https".equals(u.getScheme()))||u.getUserInfo()!=null||u.getQuery()!=null||u.getFragment()!=null||!(u.getPath().isEmpty()||u.getPath().equals("/")))throw new Exception();}catch(Exception e){host.setError("请填写有效后台地址");return;}if(pass.length()==0){pass.setError("请输入一次密码");return;}api.configure(s,pass.getText().toString());d.dismiss();connect();}));d.show();}
 void searchScreen(){body.removeAllViews();LinearLayout line=new LinearLayout(this),keys=column();keys.setPadding(0,dp(8),dp(18),0);keys.addView(text("搜到想看的",24,Color.WHITE));keys.addView(text("中文 · 首字母 · 全拼",12,Ui.ACCENT));query=new EditText(this);query.setTextColor(Color.WHITE);query.setTextSize(21);query.setSingleLine();query.setHint("例如 QYN / 庆余年");query.setHintTextColor(Ui.MUTED);query.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_CAP_CHARACTERS);query.setImeOptions(EditorInfo.IME_ACTION_SEARCH);query.setShowSoftInputOnFocus(false);keys.addView(query,new LinearLayout.LayoutParams(-1,dp(48)));String letters="ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
 for(int i=0;i<6;i++){LinearLayout row=new LinearLayout(this);for(int j=0;j<6;j++){String ch=letters.substring(i*6+j,i*6+j+1);Button b=button(ch,v->query.append(ch));LinearLayout.LayoutParams p=lp(0,27);p.weight=1;p.setMargins(dp(2),dp(2),dp(2),dp(2));row.addView(b,p);}keys.addView(row);}
 LinearLayout edit=new LinearLayout(this);for(String label:new String[]{"退格","清空","输入法"}){Button b=button(label,v->{if(label.equals("清空"))query.setText("");else if(label.equals("退格")){String s=query.getText().toString();if(!s.isEmpty())query.setText(s.substring(0,s.offsetByCodePoints(s.length(),-1)));}else{query.setShowSoftInputOnFocus(true);query.requestFocus();((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).showSoftInput(query,InputMethodManager.SHOW_IMPLICIT);}});LinearLayout.LayoutParams p=lp(0,38);p.weight=1;edit.addView(b,p);}keys.addView(edit);keys.addView(button("全名搜",v->fullNameSearch()),lp(-1,40));keys.addView(text("输入几个字母，在右侧认片\n无需逐字输入完整中文",12,Ui.MUTED));line.addView(keys,new LinearLayout.LayoutParams(dp(245),-2));LinearLayout right=column();searchStatus=text("试试 QYN / 庆余年 / 片名片段",15,Ui.MUTED);right.addView(searchStatus);suggestions=column();resultGrid=column();right.addView(suggestions);right.addView(resultGrid);line.addView(right,new LinearLayout.LayoutParams(0,-2,1));body.addView(line);
 query.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void afterTextChanged(Editable e){}public void onTextChanged(CharSequence s,int start,int before,int count){int ticket=++suggestionGeneration;handler.postDelayed(()->{if(ticket==suggestionGeneration&&current.equals("search"))suggest(s.toString(),ticket);},450);}});query.setOnEditorActionListener((v,a,e)->{if(a==EditorInfo.IME_ACTION_SEARCH){submitQuery();return true;}return false;});try{JSONArray recent=new JSONArray(api.prefs.getString("search_history","[]"));if(recent.length()>0){suggestions.addView(text("最近搜索",17,Color.WHITE));for(int i=0;i<Math.min(5,recent.length());i++){String title=recent.optString(i);suggestions.addView(button(title,v->searchActual(title)),lp(-1,40));}}}catch(Exception ignored){}
 }
 void suggest(String q,int ticket){if(q.trim().isEmpty()){suggestions.removeAllViews();resultGrid.removeAllViews();searchStatus.setText("输入首字母 / 全拼 / 片名片段，先认片，再选片源");return;}searchStatus.setText("正在联想「"+q+"」…");job(()->{JSONObject data=api.get("/tv/suggest?q="+Api.enc(q));runOnUiThread(()->{if(ticket==suggestionGeneration&&current.equals("search")&&!isFinishing())renderSuggestions(data.optJSONArray("items"));});});}
 void renderSuggestions(JSONArray items){suggestions.removeAllViews();resultGrid.removeAllViews();int n=items==null?0:items.length();searchStatus.setText(n>0?"选择想找的片名，再查可用片源":"暂无联想，试试更多字母或片名片段");for(int i=0;i<Math.min(n,12);i+=2){LinearLayout row=new LinearLayout(this);for(int j=i;j<Math.min(i+2,n);j++){JSONObject item=items.optJSONObject(j);LinearLayout c=new LinearLayout(this);c.setPadding(dp(6),dp(6),dp(6),dp(6));Ui.focus(c);c.setOnClickListener(v->searchActual(item.optString("name")));ImageView pic=new ImageView(this);Ui.image(this,pic,item.optString("pic"));c.addView(pic,new LinearLayout.LayoutParams(dp(51),dp(83)));LinearLayout words=column();words.setPadding(dp(9),dp(3),0,0);TextView title=text(item.optString("name"),15,Color.WHITE);title.setMaxLines(2);words.addView(title);words.addView(text(item.optString("typeName")+" "+item.optString("year"),12,Ui.MUTED));words.addView(text(item.optString("match","关联片名"),11,Ui.ACCENT));c.addView(words,new LinearLayout.LayoutParams(0,-1,1));LinearLayout.LayoutParams p=lp(0,103);p.weight=1;row.addView(c,p);}suggestions.addView(row);}}
 void fullNameSearch(){LinearLayout form=column();form.setPadding(dp(20),dp(8),dp(20),dp(10));form.addView(text("使用电视全键盘输入完整片名，中英文都直接查询片源。",16,Ui.MUTED));EditText full=new EditText(this);full.setSingleLine();full.setTextSize(23);full.setHint("输入完整片名，如：庆余年 第一季");full.setInputType(InputType.TYPE_CLASS_TEXT);full.setImeOptions(EditorInfo.IME_ACTION_SEARCH);full.setShowSoftInputOnFocus(true);String old=query==null?"":query.getText().toString();if(!old.matches("[A-Z0-9]{1,6}"))full.setText(old);form.addView(full,new LinearLayout.LayoutParams(-1,dp(58)));AlertDialog d=new AlertDialog.Builder(this).setTitle("全名搜 · 完整片名直接查找").setView(form).setNegativeButton("返回首字母搜索",null).setPositiveButton("搜索片源",null).create();Runnable submit=()->{String title=full.getText().toString().trim();if(title.isEmpty()){full.setError("请输入完整片名");return;}((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(full.getWindowToken(),0);d.dismiss();searchActual(title);};full.setOnEditorActionListener((v,a,e)->{if(a==EditorInfo.IME_ACTION_SEARCH){submit.run();return true;}return false;});d.setOnShowListener(x->{d.getButton(-1).setOnClickListener(v->submit.run());full.requestFocus();handler.postDelayed(()->((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).showSoftInput(full,InputMethodManager.SHOW_IMPLICIT),150);});d.show();}
 void submitQuery(){String q=query.getText().toString().trim();if(q.isEmpty())return;if(q.matches("[a-zA-Z0-9 ]+"))suggest(q,++suggestionGeneration);else searchActual(q);}
 void searchActual(String title){if(!connected){connect();return;}current="search";updateNavigation("search");searchTitle=title;if(query==null||searchStatus==null)searchScreen();suggestionGeneration++;final int ticket=++generation;searchStatus.setText("正在搜索「"+title+"」的可用片源…");suggestions.removeAllViews();resultGrid.removeAllViews();((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(query.getWindowToken(),0);try{JSONArray old=new JSONArray(api.prefs.getString("search_history","[]")),next=new JSONArray().put(title);for(int i=0;i<old.length()&&next.length()<8;i++)if(!title.equals(old.optString(i)))next.put(old.optString(i));api.prefs.edit().putString("search_history",next.toString()).apply();}catch(Exception ignored){}job(()->{JSONObject data=api.post("/api/search",new JSONObject().put("wd",title).put("sources",sources).put("filterAdult",true));runOnUiThread(()->{if(ticket==generation&&!isFinishing())renderSearch(data.optJSONArray("list"));});});}
 void renderSearch(JSONArray list){int n=list==null?0:list.length();searchStatus.setText("「"+searchTitle+"」 · "+n+" 条片源结果 · 选择版本进入详情");if(n==0){resultGrid.addView(text("暂未搜到，可换片名或稍后重试。",17,Ui.MUTED));return;}LinkedHashMap<String,JSONArray> groups=new LinkedHashMap<>();for(int i=0;i<Math.min(n,100);i++){JSONObject v=list.optJSONObject(i);if(v==null)continue;String key=v.optString("name").replaceAll("\\s+", "");JSONArray group=groups.get(key);if(group==null){group=new JSONArray();groups.put(key,group);}group.put(v);}View first=null;
 ArrayList<JSONArray> ordered=new ArrayList<>(groups.values());Collections.sort(ordered,(a,b)->Integer.compare(searchScore(b.optJSONObject(0)),searchScore(a.optJSONObject(0))));for(JSONArray group:ordered){JSONObject item=group.optJSONObject(0);LinearLayout c=new LinearLayout(this);c.setPadding(dp(7),dp(7),dp(7),dp(7));Ui.focus(c);c.setOnClickListener(v->showDetail(item,group));ImageView pic=new ImageView(this);Ui.image(this,pic,item.optString("pic"));c.addView(pic,new LinearLayout.LayoutParams(dp(70),dp(100)));LinearLayout words=column();words.setPadding(dp(12),dp(5),0,0);words.addView(text(item.optString("name"),20,Color.WHITE));words.addView(text(item.optString("year")+" "+item.optString("typeName")+" "+item.optString("remarks"),13,Ui.MUTED));words.addView(text(group.length()+" 个片源可选  ·  查看介绍与选集 ›",13,Ui.ACCENT));c.addView(words,new LinearLayout.LayoutParams(0,-1,1));resultGrid.addView(c,lp(-1,118));if(first==null)first=c;}if(first!=null)first.requestFocus();}
 int searchScore(JSONObject item){String name=item.optString("name").replaceAll("\\s+",""),q=searchTitle.replaceAll("\\s+","");int score=name.equals(q)?100:name.replaceAll("第[一1]季$","").equals(q)?90:name.startsWith(q)?70:40;if(name.matches(".*(预告|解说|花絮|剪辑).*"))score-=150;if(item.optString("typeName").contains("短剧"))score-=35;return score;}
 void openItem(JSONObject item){if(item.has("vodId"))showDetail(item,new JSONArray().put(item));else{current="search";updateNavigation("search");searchScreen();searchActual(item.optString("name"));}}
 JSONObject sourceFor(JSONObject item){for(int i=0;i<sources.length();i++){JSONObject s=sources.optJSONObject(i);if(s!=null&&(item.optString("sourceUrl").isEmpty()?s.optString("key").equals(item.optString("sourceKey")):s.optString("url").equals(item.optString("sourceUrl"))))return s;}try{return new JSONObject().put("key",item.optString("sourceKey")).put("name",item.optString("sourceName")).put("url",item.optString("sourceUrl"));}catch(Exception e){return null;}}
 void showDetail(JSONObject item,JSONArray others){JSONObject source=sourceFor(item);if(source==null)return;connection.setText("正在读取影片介绍和集数…");job(()->{JSONObject detail=api.get("/api/detail?id="+Api.enc(item.optString("vodId"))+"&source="+Api.enc(source.toString()));JSONArray choices=new JSONArray();for(int i=0;i<others.length();i++){JSONObject v=others.optJSONObject(i),s=sourceFor(v);if(s!=null)choices.put(new JSONObject().put("source",s).put("vodId",v.optString("vodId")).put("name",s.optString("name")));}detail.put("_source",source).put("_vodId",item.optString("vodId")).put("_pic",item.optString("pic")).put("_alternatives",choices);runOnUiThread(()->{connection.setText("● 已连接电脑 · 片源由电脑统一维护");if(!isFinishing())detailDialog(detail);});});}
 void detailDialog(JSONObject detail){JSONArray eps=detail.optJSONArray("episodes");if(eps==null||eps.length()==0){new AlertDialog.Builder(this).setMessage("没有可播放地址，请选择其他片源。").setPositiveButton("返回",null).show();return;}JSONObject info=detail.optJSONObject("videoInfo");if(info==null)info=new JSONObject();LinearLayout content=column();content.setPadding(dp(17),dp(8),dp(17),dp(12));LinearLayout intro=new LinearLayout(this);ImageView poster=new ImageView(this);Ui.image(this,poster,info.optString("cover",detail.optString("_pic")));intro.addView(poster,lp(100,140));LinearLayout words=column();words.setPadding(dp(16),dp(8),0,0);words.addView(text(info.optString("year")+" "+info.optString("typeName")+" · "+eps.length()+" 集",16,Ui.ACCENT));TextView desc=text(Html.fromHtml(info.optString("desc")).toString(),15,0xffc5d4de);desc.setMaxLines(5);words.addView(desc);intro.addView(words,new LinearLayout.LayoutParams(0,-2,1));content.addView(intro);JSONArray alternatives=detail.optJSONArray("_alternatives");LinearLayout sourceRow=new LinearLayout(this);sourceRow.addView(text("片源  ",16,Ui.MUTED));
 if(alternatives!=null)for(int i=0;i<alternatives.length();i++){JSONObject v=alternatives.optJSONObject(i);sourceRow.addView(button(v.optString("name"),view->{try{JSONObject s=v.optJSONObject("source"),choice=new JSONObject().put("vodId",v.optString("vodId")).put("sourceKey",s.optString("key")).put("sourceName",s.optString("name")).put("sourceUrl",s.optString("url")).put("pic",detail.optString("_pic"));JSONArray all=new JSONArray();for(int j=0;j<alternatives.length();j++){JSONObject a=alternatives.optJSONObject(j),src=a.optJSONObject("source");all.put(new JSONObject().put("vodId",a.optString("vodId")).put("sourceKey",src.optString("key")).put("sourceName",src.optString("name")).put("sourceUrl",src.optString("url")));}if(activeDetail!=null)activeDetail.dismiss();showDetail(choice,all);}catch(Exception ignored){}}),lp(110,40));}HorizontalScrollView ss=new HorizontalScrollView(this);ss.addView(sourceRow);content.addView(ss);content.addView(text("选择集数 · 播放时按下键打开控制面板",14,Ui.MUTED));
 AlertDialog dialog=new AlertDialog.Builder(this).setTitle(info.optString("title","影片")).setView(content).setNegativeButton("返回",null).create();activeDetail=dialog;LinearLayout ranges=new LinearLayout(this),episodeGrid=column();for(int i=0;i<eps.length();i+=30){final int start=i;ranges.addView(button((i+1)+"–"+Math.min(i+30,eps.length()),v->fillEpisodes(episodeGrid,detail,start,dialog)),lp(78,36));}HorizontalScrollView rs=new HorizontalScrollView(this);rs.addView(ranges);content.addView(rs);ScrollView es=new ScrollView(this);es.addView(episodeGrid);content.addView(es,new LinearLayout.LayoutParams(-1,dp(132)));fillEpisodes(episodeGrid,detail,0,dialog);dialog.show();dialog.getWindow().setLayout(dp(790),-2);}
 void fillEpisodes(LinearLayout target,JSONObject detail,int start,AlertDialog dialog){target.removeAllViews();JSONArray eps=detail.optJSONArray("episodes");for(int i=start;i<Math.min(start+30,eps.length());i+=8){LinearLayout row=new LinearLayout(this);for(int j=i;j<Math.min(i+8,Math.min(start+30,eps.length()));j++){final int selected=j;row.addView(button(eps.length()==1?"播放":String.valueOf(j+1),v->{dialog.dismiss();launch(detail,selected);}),lp(eps.length()==1?130:72,36));}target.addView(row);}}
 JSONArray history(){try{return new JSONArray(api.prefs.getString("tv_history","[]"));}catch(Exception e){return new JSONArray();}}
 void launch(JSONObject detail,int index){JSONObject info=detail.optJSONObject("videoInfo"),source=detail.optJSONObject("_source");String title=info==null?"影片":info.optString("title");try{JSONArray old=history(),next=new JSONArray();next.put(new JSONObject().put("name",title).put("pic",detail.optString("_pic",info==null?"":info.optString("cover"))).put("remarks","第"+(index+1)+"集").put("detail",detail).put("index",index));for(int i=0;i<old.length()&&next.length()<12;i++)if(!title.equals(old.optJSONObject(i).optString("name")))next.put(old.optJSONObject(i));api.prefs.edit().putString("tv_history",next.toString()).putString("recent_detail",detail.toString()).apply();}catch(Exception ignored){}
 Intent intent=new Intent(this,PlayerActivity.class);intent.putExtra("episodes",detail.optJSONArray("episodes").toString()).putExtra("index",index).putExtra("title",title).putExtra("cookie",api.cookie).putExtra("playbackKey",(source==null?title:source.optString("url"))+"|"+detail.optString("_vodId",title)).putExtra("seriesKey",title).putExtra("alternatives",detail.optJSONArray("_alternatives")==null?"[]":detail.optJSONArray("_alternatives").toString());startActivity(intent);}
 void openRecent(JSONObject item){JSONObject detail=item.optJSONObject("detail");if(detail==null)return;JSONObject source=detail.optJSONObject("_source");if(source==null){detailDialog(detail);return;}job(()->{JSONObject fresh=api.get("/api/detail?id="+Api.enc(detail.optString("_vodId"))+"&source="+Api.enc(source.toString()));fresh.put("_source",source).put("_vodId",detail.optString("_vodId")).put("_pic",detail.optString("_pic")).put("_alternatives",detail.optJSONArray("_alternatives"));runOnUiThread(()->launch(fresh,item.optInt("index",0)));});}
 void liveScreen(){body.removeAllViews();heading("频道订阅","央视、卫视与地方台");job(()->{JSONArray live=api.get("/api/status").optJSONArray("defaultLiveSources");runOnUiThread(()->{if(!current.equals("live"))return;if(live==null||live.length()==0){body.addView(text("尚未配置直播订阅",24,Color.WHITE));body.addView(text("在电脑后台配置合法可用的 M3U 订阅后，重启后台并刷新此页。\n不需要在电视上输入复杂地址。",17,Ui.MUTED));body.addView(button("刷新直播",v->liveScreen()),lp(150,44));}else for(int i=0;i<live.length();i++){JSONObject s=live.optJSONObject(i);body.addView(button(s.optString("name","直播订阅"),v->loadLive(s)),lp(-1,50));}});});}
 void loadLive(JSONObject source){job(()->{JSONArray channels=api.get("/api/live/playlist?url="+Api.enc(source.optString("url"))).optJSONArray("channels");runOnUiThread(()->{if(!current.equals("live"))return;body.removeAllViews();heading(source.optString("name"),"选择频道");if(channels!=null)for(int i=0;i<Math.min(300,channels.length());i++){JSONObject c=channels.optJSONObject(i);body.addView(button(c.optString("group")+"  "+c.optString("name"),v->{Intent intent=new Intent(this,PlayerActivity.class);intent.putExtra("episodes",new JSONArray().put(c.optString("url")).toString()).putExtra("title",c.optString("name")).putExtra("cookie",api.cookie).putExtra("playbackKey","live|"+c.optString("id")).putExtra("isLive",true);startActivity(intent);}),lp(-1,44));}});});}
 void nasScreen(String directory,int pageNumber){final int ticket=++generation;loading("正在读取电脑 NAS 影库…");job(()->{JSONObject data=api.get("/tv/nas?dir="+Api.enc(directory));runOnUiThread(()->{if(ticket!=generation||!current.equals("nas")||isFinishing())return;body.removeAllViews();heading("电脑本地影库",data.optString("rootName"));body.addView(text(directory.isEmpty()?"把电影放入后台配置的 NAS_ROOT 文件夹，再刷新即可。":directory,16,Ui.MUTED));LinearLayout actions=new LinearLayout(this);actions.addView(button("刷新",v->nasScreen(directory,pageNumber)),lp(100,40));if(!directory.isEmpty())actions.addView(button("上一级",v->nasScreen(data.optString("parent"),0)),lp(120,40));body.addView(actions);JSONArray items=data.optJSONArray("items");int count=items==null?0:items.length();if(count==0)body.addView(text("文件夹内暂时没有视频。可放入电影文件，也可以建立剧集子文件夹。",20,Ui.MUTED));
   for(int i=pageNumber*50;i<Math.min(count,(pageNumber+1)*50);i++){JSONObject item=items.optJSONObject(i);boolean folder="folder".equals(item.optString("kind"));String label=(folder?"▣  ":"▶  ")+item.optString("name")+(folder?"  ›":"    "+fileSize(item.optDouble("size")));body.addView(button(label,v->{if(folder)nasScreen(item.optString("path"),0);else{Intent intent=new Intent(this,PlayerActivity.class);intent.putExtra("episodes",new JSONArray().put(item.optString("url")).toString()).putExtra("index",0).putExtra("title",item.optString("name")).putExtra("cookie",api.cookie).putExtra("isNas",true).putExtra("playbackKey","nas|"+item.optString("path")).putExtra("seriesKey","nas|"+directory);startActivity(intent);}}),lp(-1,49));}
   LinearLayout pages=new LinearLayout(this);if(pageNumber>0)pages.addView(button("上一页",v->nasScreen(directory,pageNumber-1)),lp(110,40));if((pageNumber+1)*50<count)pages.addView(button("下一页",v->nasScreen(directory,pageNumber+1)),lp(110,40));body.addView(pages);
  });});}
 @Override public void onBackPressed(){View focus=getCurrentFocus();if(focus!=null&&activeNavigation!=null){int[] p=new int[2],s=new int[2];focus.getLocationOnScreen(p);scroll.getLocationOnScreen(s);if(p[0]>=s[0]){activeNavigation.requestFocus();return;}}if(!current.equals("home")){navigate("home");return;}new AlertDialog.Builder(this).setTitle("退出 VelaNestTV？").setPositiveButton("退出",(d,w)->finish()).setNegativeButton("继续观看",null).show();}
 @Override public boolean onKeyDown(int k,KeyEvent e){
  if(k==KeyEvent.KEYCODE_MENU){settings();return true;}
  if(k==KeyEvent.KEYCODE_DPAD_LEFT&&activeNavigation!=null){View focused=getCurrentFocus();if(focused!=null){int[] f=new int[2],s=new int[2];focused.getLocationOnScreen(f);scroll.getLocationOnScreen(s);if(f[0]>=s[0]&&f[0]<=s[0]+dp(20)){activeNavigation.requestFocus();return true;}}}
  return super.onKeyDown(k,e);
 }
 @Override public void onDestroy(){handler.removeCallbacksAndMessages(null);worker.shutdownNow();super.onDestroy();}
